  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Pamatolol absolute oral bioavailability was 64.9–103.5% after a 50 mg oral dose versus IV in healthy male subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Diacetolol mean absolute oral bioavailability was 0.426 ± 0.068 after an 800 mg oral dose versus IV, corresponding to about 43% and above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pindolol absolute oral bioavailability was 86 ± 7% in patients without renal impairment, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferred numeric evidence shows absolute oral bioavailability above 20%, mostly in the 30–100% range, supporting a high prediction. However, no supplied records directly address rifampin co-treatment, so confidence is moderate.",
  "evidence_gaps": [
    "No supplied records involve rifampin co-treatment; transfer relies on ordinary-condition absolute bioavailability.",
    "Some records are qualitative or relative rather than quantified absolute bioavailability and were not used as primary support."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

